    section5Body1: 'Isnasen n usentel n lḥiḍ ttseqdacen s waṭas isefka n cycles n zik akken ad ssirwen tikli n wakud. Mi ara llan cycles imaḍalen, isefka-a zemren ad d-ilin d aẓru.',
    section5Body2: 'Maca deg PCOS, usnifel n cycle yezmer ad yerr isefka-a ur d-ttilin ara d ayen n tidet. Asnas ur izmir ara ad yeẓṛ s tidet belli ovulation teḍra kan acku ass n tidet yewweḍ.',
    tip2Title: 'Seqdec-it d aẓru',
    tip2Text: 'Asentel amḍan yelha s waṭas akken ad twaliḍ asnifel n cycle-ik d uḥerrez n umezruy ara tebḍuḍ d umaẓrag n lɛafit.',
    section6Body1: 'Asentel amaḍal yezmer ad k-ɛawen ad tfehmeḍ asnifel-ik. Iswi mačči d ad tserreḥeḍ cycle ad yili d ayen yettwaḥerrzen, maca d ad tezdeɣeḍ talɣut iwakken ad twaliḍ asnifel.',
    trackingTips: [
      'Ruẓ-d azemz n wass amezwaru n yal cycle, ula d ma cycles ttwabeɛden aṭas',
      'Mmuqel asnifel n tidimt n ɛenq n tebburt deg cycle',
      'Ruẓ-d yal aḍṛar n teɣmert neɣ ticraḍ niḍen i izemren ad d-ilin ɣer ovulation',
      'Ur tettkeḍḍabeḍ ara kan ɣef uɣezfan amatu n 28 n wussan akken ad d-tefkeḍ ovulation',
      'Seqdec iteggi n ovulation s lehna, ma yelzem suter tanṣiḥt n win yesɛan tussna',
      'Bḍu talɣut i d-tezdiḍ d umaẓrag n lɛafit ma tebɣiḍ ad tmerneḍ',
    ],
    section6Body2: 'Yezmer daɣen ad k-ɛawen ad truẓeḍ ticraḍ i yettwaqqnen: aḍṛar, acne, asnifel n tidimt, idammen ur yelli ara d amaḍal, wul, anezgum, neɣ tamuɣli-nniḍen. Talɣut-a tezmer ad d-tefk tawlaft ugar n cycle-ik.',
    section7Body1: 'Tamsawalt tezmer ad telhu ula send ad tebduḍ ad tmerneḍ, ma cycles d iɣezfanen aṭas, ttwabeɛden aṭas, neɣ ma lḥiḍ ur d-yettili ara aṭas n wakud.',
    section7Body2: 'Amaẓrag n lɛafit yezmer ad yeẓẓi ssebbat n ugur, ad d-yefk azmiz n ovulation, d wayen ma yelzem, ad d-yernu tarrayt yellan akken ilaq i uɣrad-ik n lḥemmil.',
    alert2Title: 'Melmi ara tessuturem tisutura',
    alert2Text: 'Ma lḥiḍ-ik ttwabeɛden aṭas, ma ur d-yusi ara lḥiḍ-ik deg waṭas n wayyuren, neɣ ma ur tmerneḍ ara ɣas ma tesɛiḍ ittekkilen amaḍal, sawal ɣer umaẓrag n lɛafit.',
    summaryTitle: 'Ticraḍ igejdanin',
    summaryRows: [
      'PCOS tezmer ad tbeddel cycles ad uɣalen d iɣezfanen, ur d-yettwaḥerrzen ara.',
      'Ovulation tezmer ad tili ur yelli ara d tamaḍalt neɣ ad tettwarr deg kra n cycles.',
      'Cycle ur yelli ara d amaḍal ur yeqqar ara s wudem awurman belli ur tesɛiḍ ara tamerna.',
      'Tisewwiyin i yebnan kan ɣef uɣmis zemrent ad ttwalint ur llint ara d tidet deg PCOS.',
      'Asenqed n cycle-ik d uḥerrez n umezruy zemren ad lhun, s wudem uslig i tmesawalt.',
    ],
    finalTipTitle: 'Awal aneggaru',
    finalTipText: 'PCOS ur d-tettbegan ara akken kif kif deg yal tameṭṭut. Cycle-ik yezmer ad yettbeddil s wakud. Asentel yella akken ad k-ɛawen ad tfehmeḍ amek i yettxeddem ugraw-ik, mačči ad d-yernu tanṣiḥt n ṭṭbib.',
    disclaimer: 'Amagrad-a yettunefk kan i talɣut d uselmed. Ur d-yettaf ara asenqed n ṭṭbib, ur d-yettɛawad ara tamsawalt d umaẓrag n lɛafit.',
