    section1Body1: 'Marsaan laguu walitti hidhata mallattoo hormoonii walitti qabame irratti hundaa\'a. PCOS keessatti, qindoomina kun, keessumaa guddina folikulaa fi ovulation keessatti, jeequmsa qabaachuu danda\'a.',
    section1Body2: 'Gadaan foolikulii xixiqqaa baay\'ee of keessaa qabaachuu danda\'a, kan guddachuu jalqaban garuu folikulii olaanaan yeroo hunda gahuumsa hin argatu. Ovulation sana booda tursuu, tilmaamuu hin dandeenye ta\'uu, ykn marsaa tokko tokko keessatti hin ta\'uu danda\'a.',
    section1Body3: 'Kun sababoota tokko dha inni ta\'e namoota PCOS qaban tokko tokko marsaa guyyaa 35, 45, ykn yeroo tokko tokko isaa ol qabaatan, kaan immoo marsaa dheerina idilee irraa dhiyoo qabaatan.',
