    section4Body1: 'PCOS ulfa fudhachuu ulfaataa gochuu danda\'a, keessumaa ovulation yeroo xiqqoo ykn tilmaamuuf ulfaataa ta\'u. Haa ta\'u malee, PCOS qabaachuun da\'uu hin dandeenye jechuu miti.',
