    section4Body3: 'Da\'umsi ovulation qofa irratti hin hundaa\'u. Umuriin, qulqullina sanyii dhiirsaa, haala tuuboo faaloopiyaa, endoometriyeemii, fi wantoonni biroo gahee qabaachuu danda\'u. Kanaaf ulfi yeroo eegame caalaa yoo turu qorannoon guutuu barbaachisaa dha.',
    section5Body1: 'Appiiwwan laguu hordofan baay\'inaan odeeffannoo marsaa darbe fayyadamu tilmaama kennuuf. Marsaan yeroo madaalaan sirrii ta\'u, tilmaamni kun akka wabii bu\'a qabeessa ta\'uu danda\'a.',
    section5Body2: 'Haa ta\'u malee PCOS wajjin, jijjiiramni marsaa shallaggii kana amanamaa hin taane gochuu danda\'a. Appiin guyyaan yaadaa gahuu qofaan ovulation ta\'uu isaa mirkaneessuu hin danda\'u.',
