    section6Body2: 'ምስ ዝተኣሳሰሩ ምልክታት ምጽሓፍ እውን ክሕግዝ ይኽእል፦ ቃንዛ፣ ብጉር፣ ለውጢ ሙከስ፣ ዘይተለምደ ደም ምፍሳስ፣ ስምዒት፣ ድቃስ፣ ወይ ካልኦት ውልቃዊ ምጥማታት። እዚ ሓበሬታ ንዑደትኪ ዝመልአ ስእሊ ንምሃብ ይሕግዝ።',
    section7Body1: 'ክትጠንሲ ቅድሚ ምፍታንኪ እውን፣ ዑደታት ኣዝዮም ዘይምጉዳል፣ ኣዝዮም ዝተፈላለዩ ወይ ወርሓዊ ደም ንነዊሕ ግዜ ምስ ዘይመጽእ ምዕዛብ ጠቓሚ ክኸውን ይኽእል።',
    section7Body2: 'ሞያ ጥዕና ዘለዎ ሰብ ንምኽንያታት ዘይምጉዳል ክምርምር፣ ኦቭዩሌሽን ክገምግም፣ እንተ ኣድልዩ ድማ ንመደብ ጥንስኺ ዝስማማዕ ስትራተጂ ክሕብር ይኽእል።',
