    finalTipTitle: 'Igama lokugqibela',
    finalTipText: 'I-PCOS ayibonakali ngendlela efanayo kumfazi wonke. Umjikelo wakho unokutshintsha ngokuhamba kwexesha. Ukulandelela kukho ukukunceda uqonde ngcono indlela umzimba wakho osebenza ngayo, hayi ukuthatha indawo yecebiso lezonyango.',
    disclaimer: 'Eli nqaku lolwazi nemfundo kuphela. Alilulo uxilongo lwezonyango kwaye alithatheli indawo yophando kwingcali yezempilo.',
