    section1Body2: 'Baovaire ekoki kozala na follicule mingi ya moke oyo ebandi kokola kozanga follicule moko ya monene ekóma na kokola ya mobimba ntango nyonso. Ovulation ekoki sima kozala na nsima, kosalema na ndenge ya kokamwa, to kosalema te na basanza mosusu.',
    section1Body3: 'Yango ezali moko ya bantina mpo na nini bato mosusu oyo bazali na PCOS bazali na basanza ya mikolo 35, 45, to mbala mosusu koleka, wana basusu bazali na basanza penepene na boumeli ya mbala mingi.',
