    section5Body1: 'Ba app ya kolanda sanza mbala mingi esalelaka boyebisi ya basanza ya kala mpo na kobimisa bokanisi. Ntango basanza ezali ya mbala mingi, bokanisi oyo ekoki kosunga lokola litálisi.',
    section5Body2: 'Kasi na PCOS, bokesani ya sanza ekoki kosala ete bokanisi oyo ezala ya kotyela motema moke. App ekoki koyeba na bosikisiki te ete ovulation esalemaki kaka mpo ete mokolo ya nzela oyo ekomi.',
