      'ඩිම්බ මෝචනය පුරෝකථනය කිරීමට සාමාන්‍ය දින 28 දිග මත පමණක් විශ්වාසය තැබීම වළක්වන්න',
      'ඩිම්බ මෝචන පරීක්ෂණ ප්‍රවේශමෙන් භාවිතා කර, අවශ්‍ය නම්, වෘත්තිකයෙකුගෙන් උපදෙස් ඉල්ලන්න',
