    section1Body2: 'รังไข่อาจมีฟอลลิเคิลเล็ก ๆ จำนวนมากที่เริ่มพัฒนา โดยไม่มีฟอลลิเคิลเด่นที่เติบโตเต็มที่อย่างสม่ำเสมอ การตกไข่จึงอาจล่าช้า เกิดขึ้นโดยคาดเดาไม่ได้ หรือไม่เกิดขึ้นเลยในบางรอบเดือน',
