      'Bind bésu bu njëkk fan ci wërsëg bu nekk, lu mu mën a doon wërsëg yi tasaaru lool',
      'Seetlu soppi yu ndox mu bërëb jëmm ci wërsëg bi gépp',
      'Bind metit bu bërëb jëmm walla yeneen màndarga yu mën a ànd ak ovilasiyoŋ',
