    section1Body1: 'Zagayen haila yana dogara ga jerin siginar hormone masu daidaitawa. A PCOS, wannan tsari na iya dagulewa, musamman a girmar follicle da fitar ƙwai.',
    section1Body2: 'Ovaries na iya ƙunsar ƙananan follicles da yawa da suka fara girma ba tare da follicle mai rinjaye ya kai ga balaga akai-akai ba. Fitar ƙwai sai ta iya jinkirta, ta faru ba tare da hasashe ba, ko ba ta faru ba a wasu zagaye.',
    section1Body3: 'Wannan na ɗaya daga cikin dalilan da ya sa wasu mutane masu PCOS ke da zagaye na kwana 35, 45, ko wani lokaci fiye da haka, yayin da wasu za su iya samun zagaye kusa da tsawon al’ada.',
    tip1Title: 'Abin da ya dace a sani',
