    section2Body2: 'A zagaye mai tsari, fitar ƙwai galibi tana kusa da tsakiya. Amma da PCOS, wannan ƙa’ida mai sauƙi ba koyaushe take aiki ba. Fitar ƙwai na iya zama a ƙarshe sosai ko ba ta faru ba a wani zagaye.',
    infoTitle: 'Dalilin da ya sa wannan yake da muhimmanci',
