    section3Body1: 'Akwai alamomin jiki da dama da za su iya biyo bayan sauye-sauyen hormone a kusa da fitar ƙwai. Suna iya zama da amfani wajen lura da zagayenki na kanki, amma babu alama guda ɗaya da za ta iya tabbatar da fitar ƙwai da tabbaci.',
