    section3Body2: 'Majinar mahaifa tana da daraja musamman a lura da ita. Yayin da lokacin haihuwa ke gabatowa, tana iya yawaita, ta zama bayyananne, mai zamewa, kuma mai mikewa. Duk da haka, kamanninta na iya bambanta daga mutum zuwa mutum da daga zagaye zuwa zagaye.',
    alert1Title: 'Yi hankali da hasashe',
    alert1Text: 'Da zagaye marasa tsari sosai, ranar fitar ƙwai da aka ƙirga ta atomatik daga zagaye na baya na iya zama ƙiyasi kawai. Hasashe ba tabbacin likita ba ne na fitar ƙwai.',
    section4Body1: 'PCOS na iya sa samun ciki ya yi wahala, musamman idan fitar ƙwai ba ta faruwa akai-akai ko da wuyar hasashe. Duk da haka, samun PCOS ba ya nufin rashin haihuwa.',
    section4Body2: 'Wasu mata masu PCOS suna fitar ƙwai akai-akai kuma suna samun ciki ba tare da wahala ta musamman ba. Ga wasu, fitar ƙwai ba ta da tsari sosai har tana bukatar tantancewa da yiwuwar kulawar likita.',
