    section4Body3: 'Haihuwa ba ta dogara ga fitar ƙwai kaɗai ba, ko. Shekaru, ingancin maniyyin abokin zama, yanayin fallopian tubes, endometrium, da wasu abubuwa ma na iya taka rawa. Shi ya sa cikakken bincike yake da muhimmanci idan ciki ya ɗauki lokaci fiye da yadda ake tsammani.',
    section5Body1: 'Manhajojin bin diddigin haila yawanci suna amfani da bayanai daga zagaye na baya don samar da ƙiyasi. Idan zagaye suna da tsari sosai, waɗannan ƙiyasi na iya zama masu amfani a matsayin tunani.',
    section5Body2: 'Da PCOS kuwa, bambancin zagaye na iya sa waɗannan lissafi su zama marasa dogaro. Manhaja ba za ta iya sanin da tabbaci cewa fitar ƙwai ta faru ba kawai saboda an kai ga ranar da aka ƙiyasta.',
    tip2Title: 'Yi amfani da shi a matsayin wurin tunani',
    tip2Text: 'Bin diddigin dijital yana da amfani sosai wajen lura da tsare-tsare a zagayenki na kanki da ajiye tarihi da za a raba da ma’aikacin lafiyarki.',
    section6Body1: 'Bin diddigin akai-akai na iya taimaka miki ki fi fahimtar bambance-bambancenki na kanki. Manufar ba ita ce sa zagaye ya zama mai hasashe gaba ɗaya ba, sai dai tattara isassun bayanai don gano tsare-tsare.',
