    section6Body2: 'Hakanan yana iya taimakawa a rubuta alamomin da ke tare: ciwo, kuraje, sauyin majina, zubar jini ba na al’ada ba, yanayi, barci, ko wasu abubuwan da kika lura da su. Wannan bayani na iya taimakawa wajen gina cikakken hoto na zagayenki.',
    section7Body1: 'Shawara na iya zama da amfani ko da kafin fara neman ciki, idan zagaye ba su da tsari sosai, suna da nisa sosai, ko lokacin da haila ba ta zo na tsawon lokaci.',
