    disclaimer: 'Dit artikel is alleen bedoeld ter informatie en educatie. Het vormt geen medische diagnose en vervangt geen consult met een zorgverlener.',
    shareMessage: 'Cyclus, eisprong en vruchtbaarheid bij PCOS — AWA',
