    section1Body2: 'Munasarjoissa voi olla monia pieniä follikkeleita, jotka alkavat kehittyä ilman, että hallitseva follikkeli säännöllisesti kypsyy. Ovulaatio voi silloin viivästyä, tapahtua ennalta arvaamattomasti tai olla tapahtumatta joissakin kierroissa.',
    section1Body3: 'Tämä on yksi syistä, miksi joillakin PCOS:ää sairastavilla on 35, 45 tai joskus useamman päivän kierrot, kun taas toisilla kierrot voivat olla tyypillisemmän pituisia.',
