    section4Body3: 'Hedelmällisyys ei myöskään riipu pelkästä ovulaatiosta. Ikä, kumppanin siittiöiden laatu, munanjohtimien kunto, kohdun limakalvo ja muut tekijät voivat myös vaikuttaa. Siksi kattava arviointi on tärkeää, kun raskaus kestää odotettua pidempään.',
    section5Body1: 'Kuukautisseurantasovellukset käyttävät yleensä aiempien kiertojen tietoja arvioiden tuottamiseen. Kun kierrot ovat suhteellisen säännöllisiä, nämä arviot voivat olla hyödyllisiä viitteenä.',
    section5Body2: 'PCOS:n kanssa kierron vaihtelu voi kuitenkin tehdä näistä laskelmista vähemmän luotettavia. Sovellus ei voi tietää varmasti, että ovulaatio on tapahtunut pelkästään siksi, että teoreettinen päivämäärä on saavutettu.',
