    section6Body1: 'Säännöllinen seuranta voi auttaa ymmärtämään henkilökohtaisia vaihtelujasi. Tavoitteena ei ole tehdä kierrosta täydellisen ennustettavaa, vaan koota riittävästi tietoa trendien tunnistamiseksi.',
