    intro: 'Με PCOS, ο κύκλος σου μπορεί να γίνει μεγάλος, ακανόνιστος και μερικές φορές δύσκολος να προβλεφθεί. Η κατανόηση του τι συμβαίνει γύρω από την ωορρηξία μπορεί να σε βοηθήσει να δώσεις νόημα στον κύκλο σου και να κατανοήσεις καλύτερα τα ζητήματα γονιμότητας.',
