    section1Body1: 'Nakadepende ang siklo ng regla sa magkakaugnay na pagkakasunod-sunod ng mga hormonal na hudyat. Sa PCOS, maaaring magambala ang organisasyong ito, partikular sa pag-unlad ng follicle at sa obulasyon.',
    section1Body2: 'Maaaring maglaman ang mga obaryo ng maraming maliliit na follicle na nagsisimulang umunlad nang walang nangingibabaw na follicle na regular na umaabot sa pagkahinog. Maaaring maantala noon ang obulasyon, mangyari nang hindi mahuhulaan, o hindi mangyari sa ilang siklo.',
    section1Body3: 'Ito ang isa sa mga dahilan kung bakit may mga taong may PCOS na may siklong 35, 45, o minsan higit pang araw, habang ang iba ay maaaring may siklong mas malapit sa karaniwang haba.',
