    section2Body2: 'Sa regular na siklo, madalas nasa kalagitnaan ang obulasyon. Ngunit sa PCOS, hindi laging naaangkop ang simpleng tuntuning ito. Maaaring mas huli nang malaki ang obulasyon o maaaring hindi mangyari sa isang partikular na siklo.',
    infoTitle: 'Bakit ito mahalaga',
