    section3Body2: 'Lalong nararapat obserbahan ang cervical mucus. Habang papalapit ang panahon ng pagkamayabong, maaari itong maging mas marami, malinaw, madulas, at nababanat. Gayunpaman, maaaring mag-iba ang itsura nito sa bawat tao at sa bawat siklo.',
