    section4Body1: 'Maaaring gawing mas mahirap ng PCOS ang paglilihi, pangunahin kapag bihira o mahirap hulaan ang obulasyon. Gayunpaman, ang pagkakaroon ng PCOS ay hindi nangangahulugang baog.',
    section4Body2: 'May mga babaeng may PCOS na regular na nag-oobulate at nagbubuntis nang walang partikular na kahirapan. Para sa iba, sapat na hindi regular ang obulasyon upang mangailangan ng pagsusuri at posibleng medikal na pangangalaga.',
