    section4Body3: 'Hindi rin nakadepende sa obulasyon lamang ang pagkamayabong. Maaari ring may papel ang edad, kalidad ng tamud ng kapareha, kalagayan ng fallopian tubes, endometrium, at iba pang salik. Kaya mahalaga ang komprehensibong pagsusuri kapag mas matagal kaysa inaasahan ang pagbubuntis.',
    section5Body1: 'Karaniwang gumagamit ang mga app sa pagsubaybay ng regla ng datos mula sa mga nakaraang siklo upang gumawa ng mga tantiya. Kapag medyo regular ang mga siklo, maaaring maging kapaki-pakinabang ang mga tantiyang ito bilang sanggunian.',
    section5Body2: 'Sa PCOS, gayunpaman, maaaring gawing hindi gaanong maaasahan ng pagbabago-bago ng siklo ang mga kalkulasyong ito. Hindi tiyak na malalaman ng app na nagkaroon ng obulasyon dahil lamang naabot na ang teoretikal na petsa.',
    tip2Title: 'Gamitin ito bilang sanggunian',
