    section6Body2: 'Makakatulong din na itala ang mga kaugnay na sintomas: sakit, tigyawat, pagbabago sa mucus, hindi pangkaraniwang pagdurugo, mood, tulog, o iba pang personal na obserbasyon. Makakatulong ang impormasyong ito sa pagbuo ng mas buong larawan ng iyong siklo.',
    section7Body1: 'Maaaring sulit ang konsultasyon kahit bago pa magsimulang subukang magbuntis, kapag napakahindi regular ng mga siklo, napakalayo ng pagitan, o kapag matagal na walang regla.',
    section7Body2: 'Maaaring siyasatin ng propesyonal sa kalusugan ang mga sanhi ng iregularidad, tasahin ang obulasyon, at, kung kinakailangan, magmungkahi ng estratehiyang angkop sa iyong mga plano sa pagbubuntis.',
