    section1Body1: 'ਮਾਹਵਾਰੀ ਚੱਕਰ ਹਾਰਮੋਨੀ ਸੰਕੇਤਾਂ ਦੀ ਇੱਕ ਤਾਲਮੇਲ ਵਾਲੀ ਲੜੀ \'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ। PCOS ਵਿੱਚ ਇਹ ਪ੍ਰਬੰਧ ਵਿਗੜ ਸਕਦਾ ਹੈ, ਖ਼ਾਸ ਕਰਕੇ ਫੋਲੀਕਲ ਦੇ ਵਿਕਾਸ ਅਤੇ ਓਵੂਲੇਸ਼ਨ ਵਿੱਚ।',
    section1Body2: 'ਅੰਡਕੋਸ਼ਾਂ ਵਿੱਚ ਬਹੁਤ ਸਾਰੇ ਛੋਟੇ ਫੋਲੀਕਲ ਹੋ ਸਕਦੇ ਹਨ ਜੋ ਵਿਕਸਿਤ ਹੋਣਾ ਸ਼ੁਰੂ ਕਰਦੇ ਹਨ, ਪਰ ਕੋਈ ਪ੍ਰਮੁੱਖ ਫੋਲੀਕਲ ਨਿਯਮਿਤ ਤੌਰ \'ਤੇ ਪੱਕਦਾ ਨਹੀਂ। ਫਿਰ ਓਵੂਲੇਸ਼ਨ ਦੇਰ ਨਾਲ ਹੋ ਸਕਦਾ ਹੈ, ਅਣਕਿਆਸੇ ਢੰਗ ਨਾਲ ਹੋ ਸਕਦਾ ਹੈ, ਜਾਂ ਕੁਝ ਚੱਕਰਾਂ ਵਿੱਚ ਬਿਲਕੁਲ ਨਹੀਂ ਹੁੰਦਾ।',
    section1Body3: 'ਇਹ ਇੱਕ ਕਾਰਨ ਹੈ ਕਿ PCOS ਵਾਲੀਆਂ ਕੁਝ ਔਰਤਾਂ ਦੇ ਚੱਕਰ 35, 45 ਜਾਂ ਕਦੇ-ਕਦੇ ਇਸ ਤੋਂ ਵੱਧ ਦਿਨਾਂ ਦੇ ਹੁੰਦੇ ਹਨ, ਜਦਕਿ ਹੋਰਨਾਂ ਦੇ ਚੱਕਰ ਆਮ ਲੰਬਾਈ ਦੇ ਨੇੜੇ ਹੋ ਸਕਦੇ ਹਨ।',
    tip1Title: 'ਜਾਣਨ ਯੋਗ',
    tip1Text: 'ਸਿਰਫ਼ ਚੱਕਰ ਦੀ ਲੰਬਾਈ ਇਹ ਨਹੀਂ ਦੱਸਦੀ ਕਿ ਓਵੂਲੇਸ਼ਨ ਹੋਇਆ ਜਾਂ ਨਹੀਂ। ਇੱਕੋ ਲੰਬਾਈ ਦੇ ਦੋ ਚੱਕਰਾਂ ਦੀ ਹਾਰਮੋਨੀ ਕਹਾਣੀ ਵੱਖਰੀ ਹੋ ਸਕਦੀ ਹੈ।',
    section2Body1: 'ਓਵੂਲੇਸ਼ਨ ਅੰਡਕੋਸ਼ ਵਿੱਚੋਂ ਅੰਡੇ ਦਾ ਨਿਕਲਣਾ ਹੈ। ਇਹ ਫੋਲੀਕਲ ਦੇ ਪੱਕਣ ਦੇ ਪੜਾਅ ਤੋਂ ਬਾਅਦ ਅਤੇ ਚੱਕਰ ਦੇ ਲਿਊਟੀਅਲ ਪੜਾਅ ਤੋਂ ਪਹਿਲਾਂ ਹੁੰਦਾ ਹੈ।',
    section2Body2: 'ਨਿਯਮਿਤ ਚੱਕਰ ਵਿੱਚ ਓਵੂਲੇਸ਼ਨ ਅਕਸਰ ਵਿਚਕਾਰਲੇ ਸਮੇਂ ਦੇ ਆਸ-ਪਾਸ ਹੁੰਦਾ ਹੈ। ਪਰ PCOS ਵਿੱਚ ਇਹ ਸਾਦਾ ਨਿਯਮ ਹਮੇਸ਼ਾ ਲਾਗੂ ਨਹੀਂ ਹੁੰਦਾ। ਕਿਸੇ ਚੱਕਰ ਵਿੱਚ ਓਵੂਲੇਸ਼ਨ ਬਹੁਤ ਦੇਰ ਨਾਲ ਹੋ ਸਕਦਾ ਹੈ ਜਾਂ ਹੋ ਹੀ ਨਹੀਂ ਸਕਦਾ।',
