    infoText: 'ਜਦੋਂ ਓਵੂਲੇਸ਼ਨ ਦਾ ਅੰਦਾਜ਼ਾ ਨਾ ਲੱਗੇ, ਤਾਂ ਸਿਰਫ਼ ਮਾਹਵਾਰੀ ਦੀਆਂ ਤਾਰੀਖ਼ਾਂ ਦੇ ਆਧਾਰ \'ਤੇ ਉਪਜਾਊ ਸਮੇਂ ਦਾ ਅੰਦਾਜ਼ਾ ਲਾਉਣਾ ਹੋਰ ਔਖਾ ਹੋ ਜਾਂਦਾ ਹੈ।',
    section3Body1: 'ਕਈ ਸਰੀਰਕ ਸੰਕੇਤ ਹਨ ਜੋ ਓਵੂਲੇਸ਼ਨ ਦੇ ਆਸ-ਪਾਸ ਹਾਰਮੋਨੀ ਬਦਲਾਵਾਂ ਦੇ ਨਾਲ ਆ ਸਕਦੇ ਹਨ। ਇਹ ਆਪਣੇ ਚੱਕਰ ਨੂੰ ਦੇਖਣ ਲਈ ਲਾਭਦਾਇਕ ਹੋ ਸਕਦੇ ਹਨ, ਪਰ ਕੋਈ ਇੱਕ ਸੰਕੇਤ ਓਵੂਲੇਸ਼ਨ ਦੀ ਪੱਕੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰ ਸਕਦਾ।',
