    section3Body2: 'ਬੱਚੇਦਾਨੀ ਦੇ ਮੂੰਹ ਦੇ ਰਿਸਾਅ ਨੂੰ ਖ਼ਾਸ ਤੌਰ \'ਤੇ ਦੇਖਣਾ ਚਾਹੀਦਾ ਹੈ। ਜਿਵੇਂ-ਜਿਵੇਂ ਉਪਜਾਊ ਸਮਾਂ ਨੇੜੇ ਆਉਂਦਾ ਹੈ, ਇਹ ਵਧੇਰੇ ਮਾਤਰਾ ਵਾਲਾ, ਸਾਫ਼, ਤਿਲਕਣ ਵਾਲਾ ਅਤੇ ਖਿੱਚਣ ਯੋਗ ਹੋ ਸਕਦਾ ਹੈ। ਫਿਰ ਵੀ, ਇਸ ਦਾ ਰੂਪ ਹਰ ਵਿਅਕਤੀ ਅਤੇ ਹਰ ਚੱਕਰ ਵਿੱਚ ਵੱਖ ਹੋ ਸਕਦਾ ਹੈ।',
