    section4Body3: 'ਉਪਜਾਊ ਸ਼ਕਤੀ ਸਿਰਫ਼ ਓਵੂਲੇਸ਼ਨ \'ਤੇ ਵੀ ਨਿਰਭਰ ਨਹੀਂ ਕਰਦੀ। ਉਮਰ, ਸਾਥੀ ਦੇ ਸ਼ੁਕਰਾਣੂਆਂ ਦੀ ਗੁਣਵੱਤਾ, ਫੈਲੋਪੀਅਨ ਨਲੀਆਂ ਦੀ ਹਾਲਤ, ਬੱਚੇਦਾਨੀ ਦੀ ਅੰਦਰਲੀ ਪਰਤ ਅਤੇ ਹੋਰ ਕਾਰਕ ਵੀ ਭੂਮਿਕਾ ਨਿਭਾ ਸਕਦੇ ਹਨ। ਇਸੇ ਲਈ ਜਦੋਂ ਗਰਭ-ਅਵਸਥਾ ਉਮੀਦ ਤੋਂ ਵੱਧ ਸਮਾਂ ਲਵੇ, ਤਾਂ ਸੰਪੂਰਨ ਜਾਂਚ ਮਾਇਨੇ ਰੱਖਦੀ ਹੈ।',
    section5Body1: 'ਮਾਹਵਾਰੀ ਦਾ ਰਿਕਾਰਡ ਰੱਖਣ ਵਾਲੀਆਂ ਐਪਾਂ ਆਮ ਤੌਰ \'ਤੇ ਅੰਦਾਜ਼ੇ ਬਣਾਉਣ ਲਈ ਪਿਛਲੇ ਚੱਕਰਾਂ ਦੇ ਅੰਕੜੇ ਵਰਤਦੀਆਂ ਹਨ। ਜਦੋਂ ਚੱਕਰ ਮੁਕਾਬਲਤਨ ਨਿਯਮਿਤ ਹੋਣ, ਤਾਂ ਇਹ ਅੰਦਾਜ਼ੇ ਇੱਕ ਹਵਾਲੇ ਵਜੋਂ ਲਾਭਦਾਇਕ ਹੋ ਸਕਦੇ ਹਨ।',
    section5Body2: 'ਪਰ PCOS ਵਿੱਚ, ਚੱਕਰ ਦੀ ਅਨਿਯਮਿਤਤਾ ਇਨ੍ਹਾਂ ਗਿਣਤੀਆਂ ਨੂੰ ਘੱਟ ਭਰੋਸੇਯੋਗ ਬਣਾ ਸਕਦੀ ਹੈ। ਕੋਈ ਐਪ ਪੱਕੇ ਤੌਰ \'ਤੇ ਨਹੀਂ ਜਾਣ ਸਕਦੀ ਕਿ ਓਵੂਲੇਸ਼ਨ ਹੋ ਗਿਆ ਹੈ, ਸਿਰਫ਼ ਇਸ ਲਈ ਕਿ ਇੱਕ ਸਿਧਾਂਤਕ ਤਾਰੀਖ਼ ਆ ਗਈ ਹੈ।',
    tip2Title: 'ਇਸ ਨੂੰ ਇੱਕ ਹਵਾਲੇ ਵਜੋਂ ਵਰਤੋ',
    tip2Text: 'ਡਿਜੀਟਲ ਰਿਕਾਰਡ ਆਪਣੇ ਚੱਕਰ ਦੇ ਰੁਝਾਨ ਦੇਖਣ ਅਤੇ ਆਪਣੇ ਸਿਹਤ ਸੇਵਾ-ਦਾਤਾ ਨਾਲ ਸਾਂਝਾ ਕਰਨ ਲਈ ਇਤਿਹਾਸ ਰੱਖਣ ਵਿੱਚ ਸਭ ਤੋਂ ਵੱਧ ਲਾਭਦਾਇਕ ਹੁੰਦਾ ਹੈ।',
    section6Body1: 'ਨਿਯਮਿਤ ਰਿਕਾਰਡ ਰੱਖਣਾ ਤੁਹਾਨੂੰ ਆਪਣੇ ਨਿੱਜੀ ਬਦਲਾਵਾਂ ਨੂੰ ਬਿਹਤਰ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ। ਮਕਸਦ ਚੱਕਰ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਅੰਦਾਜ਼ੇ ਯੋਗ ਬਣਾਉਣਾ ਨਹੀਂ ਹੈ, ਸਗੋਂ ਰੁਝਾਨ ਪਛਾਣਨ ਲਈ ਕਾਫ਼ੀ ਜਾਣਕਾਰੀ ਇਕੱਠੀ ਕਰਨਾ ਹੈ।',
