    section3Body1: 'မျိုးဥကြွေချိန်ဝန်းကျင်ရှိ ဟော်မုန်းပြောင်းလဲမှုများနှင့်အတူ ဖြစ်ပေါ်နိုင်သည့် ခန္ဓာကိုယ်လက္ခဏာများ အများအပြား ရှိသည်။ ၎င်းတို့သည် သင့်ကိုယ်ပိုင် ရာသီစက်ဝန်းကို လေ့လာရာတွင် အသုံးဝင်နိုင်သော်လည်း လက္ခဏာတစ်ခုတည်းဖြင့် မျိုးဥကြွေခြင်းကို သေချာစွာ အတည်ပြုနိုင်မည် မဟုတ်ပါ။',
