    section3Body2: 'သားအိမ်ခေါင်းအချွဲကို အထူးသဖြင့် လေ့လာကြည့်ရှုသင့်သည်။ သန္ဓေတည်လွယ်သည့်ကာလ နီးလာသည်နှင့်အမျှ ၎င်းသည် ပိုများလာပြီး ကြည်လင်၊ ချော၍ ဆန့်နိုင်လာနိုင်သည်။ သို့သော် ၎င်း၏ ပုံပန်းသဏ္ဌာန်သည် လူတစ်ဦးနှင့်တစ်ဦး၊ ရာသီစက်ဝန်းတစ်ခုနှင့်တစ်ခု ကွဲပြားနိုင်သည်။',
