    tip2Text: 'ការតាមដានតាមឌីជីថលមានប្រយោជន៍បំផុតសម្រាប់សង្កេតនិន្នាការនៃវដ្តរដូវរបស់អ្នក និងរក្សាប្រវត្តិដើម្បីចែករំលែកជាមួយអ្នកជំនាញសុខាភិបាលរបស់អ្នក។',
